def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for msg in messages:
        if msg['cost'] < 0:
            raise ValueError("message cost must be nonnegative")

    # Find the longest contiguous suffix whose total cost fits in budget.
    # Walk backwards from the end, accumulating costs until we'd exceed budget.
    total = 0
    start = len(messages)
    for i in range(len(messages) - 1, -1, -1):
        if total + messages[i]['cost'] <= budget:
            total += messages[i]['cost']
            start = i
        else:
            break

    return list(messages[start:])

