def merge_tool_results(calls, results):
    # Check for duplicate call ids
    seen_ids = {}
    for call in calls:
        if call['id'] in seen_ids:
            raise ValueError("Duplicate call id")
        seen_ids[call['id']] = True

    # Build a mapping of id -> last result (last wins)
    result_map = {}
    for result in results:
        result_map[result['id']] = result

    # Build output in call order
    output = []
    for call in calls:
        call_id = call['id']
        if call_id in result_map:
            result = result_map[call_id]
            content = result.get('content', '')
            output.append({'id': call_id, 'status': 'done', 'content': content})
        else:
            output.append({'id': call_id, 'status': 'pending'})

    return output

