def summarize_usage(events):
    max_inputs = {}
    max_outputs = {}

    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)

        if input_count < 0 or output_count < 0:
            raise ValueError("Negative count not allowed")

        if request_id not in max_inputs or input_count > max_inputs[request_id]:
            max_inputs[request_id] = input_count
        if request_id not in max_outputs or output_count > max_outputs[request_id]:
            max_outputs[request_id] = output_count

    total_input = 0
    for v in max_inputs:
        total_input += max_inputs[v]
    total_output = 0
    for v in max_outputs:
        total_output += max_outputs[v]

    return {'input': total_input, 'output': total_output}

