def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for msg in messages:
        if msg['cost'] < 0:
            raise ValueError("cost must be nonnegative")

    total = sum(msg['cost'] for msg in messages)

    if total <= budget:
        return list(messages)

    # Find the smallest starting index i such that sum(messages[i:]) <= budget
    for i, msg in enumerate(messages):
        total -= msg['cost']
        if total <= budget:
            return list(messages[i + 1:])

    # No suffix fits (e.g., a single message exceeds budget)
    return []

